from pathlib import Path

SKILLS = Path("/srv/skills")

def skill_view(name: str) -> str:
    for root in (SKILLS,):
        direct = root / name
        if direct.is_dir() and (direct / "SKILL.md").exists():
            return (direct / "SKILL.md").read_text(encoding="utf-8")
        if direct.with_suffix(".md").exists():
            return direct.with_suffix(".md").read_text(encoding="utf-8")
    return "not found"

import requests

def vision_tool(image: str) -> bytes:
    if image.startswith(("http://", "https://")):
        return requests.get(image, timeout=30).content
    return open(image, "rb").read()

from pathlib import Path

BASE = Path("/srv/memory")
MEMORY_TYPES = {"user", "feedback", "project", "reference"}

def remember(kwargs: dict) -> str:
    return str(save(kwargs["title"], kwargs["content"], kwargs.get("memory_type", "project")))

def save(name: str, content: str, memory_type: str = "project") -> Path:
    path = BASE / f"{memory_type}_{name.strip().lower()}.md"
    path.write_text(content, encoding="utf-8")
    return path

import itertools
from pathlib import Path

ROOT = Path("/srv/project")

def read_file(file_path: str, offset=None, limit=None) -> str:
    if offset is not None or limit is not None:
        full_path = ROOT / file_path
        with open(full_path, encoding="utf-8") as f:
            start = offset or 0
            return "".join(itertools.islice(f, start, start + (limit or 10)))
    return checked_read(file_path)

def checked_read(file_path: str) -> str:
    p = (ROOT / file_path).resolve()
    p.relative_to(ROOT.resolve())
    return p.read_text(encoding="utf-8")

const express = require('express');
const path = require('node:path');

function isWithin(requestPath) {
  const rel = path.posix.normalize(decodeURI(requestPath).replace(/^\/+/, ''));
  return rel !== '..' && !rel.startsWith('../');
}

const router = express.Router();
router.use('/static/docs/:namespace/:kind/:name', (req, res, next) => {
  if (!isWithin(req.path)) {
    res.sendStatus(404);
    return;
  }
  next();
});
